namespace RecipeCommunity.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

public class RecipeSubmission
{
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
}

using RecipeCommunity.Models;

namespace RecipeCommunity.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes =
    [
        new()
        {
            Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
            Description = "A simple, classic pizza with fresh mozzarella, tomatoes, and basil.",
            Ingredients = ["Pizza dough", "San Marzano tomatoes", "Fresh mozzarella", "Fresh basil", "Olive oil", "Salt"],
            Steps =
            [
                "Preheat oven to 475°F (245°C) with a pizza stone if available.",
                "Stretch dough into a 12-inch round on a floured surface.",
                "Spread crushed tomatoes evenly, leaving a 1-inch border.",
                "Tear mozzarella into pieces and distribute over the sauce.",
                "Bake for 10–12 minutes until crust is golden and cheese is bubbling.",
                "Top with fresh basil leaves and a drizzle of olive oil."
            ],
            AverageRating = 4.5, RatingCount = 24
        },
        new()
        {
            Id = 2, Title = "Spaghetti Carbonara", Category = "Italian",
            Description = "Creamy Roman pasta made with eggs, cheese, pancetta, and black pepper.",
            Ingredients = ["Spaghetti", "Pancetta", "Eggs", "Pecorino Romano", "Black pepper", "Salt"],
            Steps =
            [
                "Cook spaghetti in salted boiling water until al dente.",
                "Crisp pancetta in a skillet over medium heat.",
                "Whisk eggs with grated Pecorino and plenty of black pepper.",
                "Drain pasta, reserving 1 cup of pasta water.",
                "Toss hot pasta with pancetta, then remove from heat.",
                "Pour egg mixture over pasta, tossing quickly to create a creamy sauce. Add pasta water as needed."
            ],
            AverageRating = 4.7, RatingCount = 31
        },
        new()
        {
            Id = 3, Title = "Chicken Tikka Masala", Category = "Indian",
            Description = "Tender chicken pieces in a rich, spiced tomato-cream sauce.",
            Ingredients = ["Chicken breast", "Yogurt", "Garam masala", "Tomato sauce", "Heavy cream", "Onion", "Garlic", "Ginger", "Cumin", "Turmeric"],
            Steps =
            [
                "Marinate chicken in yogurt, garam masala, and salt for at least 1 hour.",
                "Grill or broil chicken until charred and cooked through.",
                "Sauté onion, garlic, and ginger in oil until softened.",
                "Add spices and cook for 1 minute until fragrant.",
                "Stir in tomato sauce and simmer for 15 minutes.",
                "Add cream and cooked chicken, simmer 5 more minutes."
            ],
            AverageRating = 4.8, RatingCount = 42
        },
        new()
        {
            Id = 4, Title = "Vegetable Biryani", Category = "Indian",
            Description = "Fragrant layered rice dish with mixed vegetables and aromatic spices.",
            Ingredients = ["Basmati rice", "Mixed vegetables", "Onion", "Yogurt", "Saffron", "Whole spices", "Ghee", "Mint", "Cilantro"],
            Steps =
            [
                "Soak basmati rice for 30 minutes, then parboil until 70% cooked.",
                "Fry sliced onions in ghee until deep golden brown.",
                "Cook vegetables with yogurt and ground spices.",
                "Layer rice and vegetable mixture in a heavy-bottomed pot.",
                "Drizzle saffron milk and top with fried onions, mint, and cilantro.",
                "Seal the pot and cook on low heat for 20 minutes."
            ],
            AverageRating = 4.3, RatingCount = 18
        },
        new()
        {
            Id = 5, Title = "Beef Tacos", Category = "Mexican",
            Description = "Seasoned ground beef in warm tortillas with fresh toppings.",
            Ingredients = ["Ground beef", "Taco seasoning", "Corn tortillas", "Lettuce", "Tomato", "Cheddar cheese", "Sour cream", "Lime"],
            Steps =
            [
                "Brown ground beef in a skillet over medium-high heat.",
                "Add taco seasoning and water, simmer until thickened.",
                "Warm tortillas in a dry skillet or microwave.",
                "Assemble tacos with beef, shredded lettuce, diced tomato, and cheese.",
                "Top with sour cream and a squeeze of lime."
            ],
            AverageRating = 4.2, RatingCount = 15
        },
        new()
        {
            Id = 6, Title = "Guacamole", Category = "Mexican",
            Description = "Fresh, creamy avocado dip with lime, cilantro, and a kick of jalapeño.",
            Ingredients = ["Avocados", "Lime juice", "Cilantro", "Red onion", "Jalapeño", "Tomato", "Salt"],
            Steps =
            [
                "Halve and pit avocados, scoop flesh into a bowl.",
                "Mash with a fork to desired consistency.",
                "Stir in diced onion, jalapeño, tomato, and cilantro.",
                "Add lime juice and salt to taste.",
                "Serve immediately with tortilla chips."
            ],
            AverageRating = 4.6, RatingCount = 28
        },
        new()
        {
            Id = 7, Title = "Chocolate Lava Cake", Category = "Desserts",
            Description = "Rich individual chocolate cakes with a molten center.",
            Ingredients = ["Dark chocolate", "Butter", "Eggs", "Sugar", "Flour", "Vanilla extract"],
            Steps =
            [
                "Preheat oven to 425°F (220°C). Butter and flour ramekins.",
                "Melt chocolate and butter together, stir until smooth.",
                "Whisk eggs, sugar, and vanilla until thick and pale.",
                "Fold chocolate mixture into the eggs, then fold in flour.",
                "Divide batter among ramekins and bake 12–14 minutes.",
                "Let cool 1 minute, then invert onto plates. Serve immediately."
            ],
            AverageRating = 4.9, RatingCount = 55
        },
        new()
        {
            Id = 8, Title = "Miso Ramen", Category = "Japanese",
            Description = "Hearty noodle soup with a rich miso-based broth and savory toppings.",
            Ingredients = ["Ramen noodles", "Miso paste", "Chicken broth", "Soy sauce", "Sesame oil", "Soft-boiled egg", "Chashu pork", "Green onions", "Nori"],
            Steps =
            [
                "Bring chicken broth to a simmer in a pot.",
                "Whisk in miso paste and soy sauce; keep warm.",
                "Cook ramen noodles according to package directions.",
                "Prepare soft-boiled eggs (6.5 minutes in boiling water).",
                "Divide noodles among bowls and ladle broth over them.",
                "Top with sliced chashu, halved egg, green onions, and nori."
            ],
            AverageRating = 4.6, RatingCount = 33
        }
    ];

    // In-memory rating storage (per recipe id → list of ratings)
    private readonly Dictionary<int, List<int>> _ratings = [];

    public List<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();

    public List<Recipe> GetRecipesByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetRecipeById(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        if (stars is < 1 or > 5) return;
        if (!_ratings.ContainsKey(recipeId))
            _ratings[recipeId] = [];

        _ratings[recipeId].Add(stars);

        var recipe = GetRecipeById(recipeId);
        if (recipe is null) return;

        recipe.RatingCount++;
        recipe.AverageRating = Math.Round(
            (recipe.AverageRating * (recipe.RatingCount - 1) + stars) / recipe.RatingCount, 1);
    }

    public void SubmitRecipe(RecipeSubmission submission)
    {
        var newId = _recipes.Max(r => r.Id) + 1;
        _recipes.Add(new Recipe
        {
            Id = newId,
            Title = submission.Title,
            Category = submission.Category,
            Description = $"A community-submitted {submission.Category.ToLowerInvariant()} recipe.",
            Ingredients = submission.Ingredients
                .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                .ToList(),
            Steps = submission.Steps
                .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                .ToList(),
            AverageRating = 0,
            RatingCount = 0
        });
    }
}

