@page "/"
@using RecipeCommunity.Services

<PageTitle>Recipe Community</PageTitle>

<div class="hero">
    <h1>🍳 Recipe Community</h1>
    <p class="lead">Discover, share, and rate delicious recipes from around the world.</p>
</div>

<h2 class="mt-4">Browse by Category</h2>
<div class="row mt-3">
    @foreach (var category in _categories)
    {
        <div class="col-md-4 col-sm-6 mb-4">
            <div class="card h-100 category-card shadow-sm">
                <div class="card-body text-center">
                    <h3 class="card-title">
                        <span class="category-icon">@GetCategoryIcon(category)</span>
                        @category
                    </h3>
                    <p class="card-text text-muted">
                        @_recipeService.GetRecipesByCategory(category).Count recipe(s)
                    </p>
                    <a href="/category/@category" class="btn btn-outline-primary">View Recipes</a>
                </div>
            </div>
        </div>
    }
</div>

<div class="text-center mt-4 mb-4">
    <a href="/submit" class="btn btn-success btn-lg">📝 Submit Your Own Recipe</a>
</div>

@code {
    [Inject] private RecipeService _recipeService { get; set; } = default!;

    private List<string> _categories = [];

    protected override void OnInitialized()
    {
        _categories = _recipeService.GetCategories();
    }

    private static string GetCategoryIcon(string category) => category switch
    {
        "Italian" => "🍝",
        "Indian" => "🍛",
        "Mexican" => "🌮",
        "Japanese" => "🍜",
        "Desserts" => "🍰",
        _ => "🍽️"
    };
}

