        </div>

        <div class="mb-3">
            <label for="ingredients" class="form-label">Ingredients</label>
            <InputTextArea id="ingredients" @bind-Value="_model.Ingredients" class="form-control" rows="5"
                           placeholder="Enter one ingredient per line&#10;e.g.,&#10;2 cups flour&#10;1 cup sugar&#10;3 eggs" />
            <ValidationMessage For="() => _model.Ingredients" />
        </div>

        <div class="mb-3">
            <label for="steps" class="form-label">Steps</label>
            <InputTextArea id="steps" @bind-Value="_model.Steps" class="form-control" rows="6"
                           placeholder="Enter one step per line&#10;e.g.,&#10;Preheat oven to 350°F.&#10;Mix dry ingredients.&#10;Add wet ingredients and stir." />
            <ValidationMessage For="() => _model.Steps" />
        </div>

        <button type="submit" class="btn btn-success"
                disabled="@(string.IsNullOrWhiteSpace(_model.Title) || string.IsNullOrWhiteSpace(_model.Category) || string.IsNullOrWhiteSpace(_model.Ingredients) || string.IsNullOrWhiteSpace(_model.Steps))">
            Submit Recipe
        </button>
        <a href="/" class="btn btn-outline-secondary ms-2">Cancel</a>
    </EditForm>
}

@code {
    [Inject] private RecipeService _recipeService { get; set; } = default!;

    private RecipeSubmission _model = new();
    private List<string> _categories = [];
    private bool _submitted;

    protected override void OnInitialized()
    {
        _categories = _recipeService.GetCategories();
    }

    private void HandleSubmit()
    {
        if (string.IsNullOrWhiteSpace(_model.Title) || string.IsNullOrWhiteSpace(_model.Category)
            || string.IsNullOrWhiteSpace(_model.Ingredients) || string.IsNullOrWhiteSpace(_model.Steps))
            return;

        _recipeService.SubmitRecipe(_model);
        _submitted = true;
    }

    private void Reset()
    {
        _model = new RecipeSubmission();
        _submitted = false;
    }
}

